export function getCandidateExam(id: string) {
  return CANDIDATE_EXAMS.find((exam) => exam.id === id) ?? null;
}

export const SCHEDULED_CANDIDATE_EXAMS = CANDIDATE_EXAMS.filter((exam) => exam.kind === "scheduled");

export function isScheduledExamId(id: string): boolean {
  return SCHEDULED_CANDIDATE_EXAMS.some((exam) => exam.id === id);
}
